/* Complete HCPS response preparation model. Native browser/Node built-ins only. */
(function(global){
"use strict";
const FORMAT="commons.hcps.response-workspace.v1", MAX_FILE=32*1024*1024,MAX_TOTAL=128*1024*1024;
const SOURCE_IDENTITIES={"HCPS_0562FAC_RESPONSE_PRODUCTION.md":{"bytes":22013,"sha256":"363ca13784a081ca074cfc79dff712e0d16604c857c35ec23b965f6c61018e51"},"HCPS_0562FAC_REQUIREMENTS.json":{"bytes":46488,"sha256":"80e21dc53f44f66b17820f213ce5d15fb318147c9018c7742387af4c16739998"},"HCPS_0562FAC_TIMED_PRESENTATION_SCRIPT.json":{"bytes":8349,"sha256":"1a8b9b5e2d1c1f9caa0b512ff2612074a49b0cbd8e669005837ff44d7419ac9a"},"HCPS_0562FAC_Original_RFQ_Readable.txt":{"bytes":123496,"sha256":"aa018d7ba41138e0c48d758db4852d63511d001f929996aa0ea886032154dbe9"}};
const STATUS=["open","in-progress","ready-for-review","complete","not-applicable"];
const ROLE=["source","cover","checklist","form","licence","reference","evidence","presentation","other"];
const clone=v=>JSON.parse(JSON.stringify(v));
function need(value,message){if(!value)throw Error(message);}
function object(v){return v&&typeof v==="object"&&!Array.isArray(v);}
function str(v,n=10000){need(typeof v==="string"&&v.length<=n,"Keep complete bounded text fields.");return v;}
function equal(a,b){return canonical(a)===canonical(b);}
function canonical(v){if(v===null)return"null";if(typeof v==="string"||typeof v==="boolean")return JSON.stringify(v);if(typeof v==="number"){need(Number.isFinite(v),"Numbers must be finite.");return Object.is(v,-0)?"-0":JSON.stringify(v);}if(Array.isArray(v))return"["+v.map(canonical).join(",")+"]";need(object(v),"Unsupported JSON value.");return"{"+Object.keys(v).sort().map(k=>JSON.stringify(k)+":"+canonical(v[k])).join(",")+"}";}
function bytes(v){return new TextEncoder().encode(typeof v==="string"?v:canonical(v));}
async function sha(value){const raw=typeof value==="string"?bytes(value):value;return Array.from(new Uint8Array(await global.crypto.subtle.digest("SHA-256",raw))).map(x=>x.toString(16).padStart(2,"0")).join("");}
function b64(raw){let s="";for(let i=0;i<raw.length;i+=32768)s+=String.fromCharCode(...raw.subarray(i,i+32768));return btoa(s);}
function unb64(value){str(value,Math.ceil(MAX_FILE/3)*4+4);need(/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value),"Use a complete canonical Base64 document.");const s=atob(value);const raw=Uint8Array.from(s,c=>c.charCodeAt(0));need(b64(raw)===value,"Original document Base64 differs.");return raw;}
function id(){return global.crypto.randomUUID();}
function original(seed){need(object(seed)&&seed.format==="commons.hcps.production-seed.v1"&&Array.isArray(seed.files),"Retain the complete original production seed.");const map=Object.fromEntries(seed.files.map(f=>[f.path,f]));need(Object.keys(map).length===seed.files.length,"Original source names must be unique.");return{requirements:JSON.parse(map["HCPS_0562FAC_REQUIREMENTS.json"].content),script:JSON.parse(map["HCPS_0562FAC_TIMED_PRESENTATION_SCRIPT.json"].content),guide:map["HCPS_0562FAC_RESPONSE_PRODUCTION.md"].content,rfq:map["HCPS_0562FAC_Original_RFQ_Readable.txt"].content};}
async function validateSeed(seed){original(seed);need(seed.files.length===Object.keys(SOURCE_IDENTITIES).length,"Keep the complete original source selection.");for(const f of seed.files){need(SOURCE_IDENTITIES[f.path]&&SOURCE_IDENTITIES[f.path].bytes===f.bytes&&SOURCE_IDENTITIES[f.path].sha256===f.sha256,"Keep the selected original issued-source edition.");str(f.path,240);str(f.content,2000000);need(f.bytes===bytes(f.content).length&&f.sha256===await sha(f.content),"An original complete issuer/source member differs: "+f.path);}return seed;}
function newWorkspace(seed){const o=original(seed);return{format:FORMAT,workspaceId:id(),title:"HCPS 0562FAC response preparation",seed:clone(seed),draft:{actor:"",note:"",firmName:"",contact:"",requirements:o.requirements.requirements.map(r=>({id:r.id,status:"open",note:"",reviewer:"",decisionDate:"",evidence:[]})),slides:clone(o.script.slides),documents:[],assembly:[],matrix:{documentId:"",page:13,reviewer:"",note:"",reviewed:false},summaries:{documentId:"",reviewer:"",note:"",reviewed:false}},objects:{},editions:[],receiving:[]};}
function ready(w){const o=original(w.seed),d=w.draft;const issues=[];if(!d.firmName.trim())issues.push("Enter the approved legal firm name.");if(!d.contact.trim())issues.push("Enter the approved contact details.");for(const r of d.requirements){const source=o.requirements.requirements.find(x=>x.id===r.id);if(source.lifecycle.startsWith("pursuit")&&!["complete","not-applicable"].includes(r.status))issues.push(r.id+": "+source.requirement);if(["complete","not-applicable"].includes(r.status)&&(!r.reviewer.trim()||!r.decisionDate||!r.note.trim()))issues.push(r.id+": record reviewer, decision date and basis.");if(r.status==="complete"&&!r.evidence.length)issues.push(r.id+": attach the original completion evidence.");}
if(!d.matrix.reviewed||!d.matrix.documentId||!d.matrix.reviewer.trim())issues.push("Review the issued page13 matrix against an attached original.");if(!d.summaries.reviewed||!d.summaries.documentId||!d.summaries.reviewer.trim())issues.push("Review the issuer's original sample summary slides.");for(const s of d.slides){if(/\[[^\]]+\]/.test(s.body)||!s.title.trim()||!s.body.trim())issues.push(s.id+": complete the approved factual content.");}const total=d.slides.reduce((s,r)=>s+r.seconds,0);if(total>240)issues.push("The presentation exceeds240seconds.");return{ready:issues.length===0,durationSeconds:total,issues};}
function validateDraft(d,seed){need(object(d),"Keep the whole editable working content.");for(const k of ["actor","note","firmName","contact"])str(d[k],k==="note"?12000:1000);const o=original(seed),wanted=o.requirements.requirements.map(r=>r.id);need(Array.isArray(d.requirements)&&d.requirements.length===wanted.length,"Retain all56 requirements.");need(equal(d.requirements.map(r=>r.id),wanted),"Keep every original requirement and its order.");need(Array.isArray(d.documents)&&d.documents.length<=200,"At most200 complete documents.");const docs=new Map();let total=0;for(const f of d.documents){need(object(f)&&typeof f.id==="string"&&!docs.has(f.id),"Use unique original document identities.");str(f.id,200);str(f.name,240);need(f.name&&!/[/\\\0]/.test(f.name),"Use an ordinary document filename.");str(f.mediaType,200);str(f.sourceUrl,3000);str(f.note,12000);need(ROLE.includes(f.role),"Choose a documented document role.");need(Number.isSafeInteger(f.bytes)&&f.bytes>=0&&f.bytes<=MAX_FILE&&/^[a-f0-9]{64}$/.test(f.sha256),"A document size/hash is invalid.");total+=f.bytes;docs.set(f.id,f);}need(total<=MAX_TOTAL,"Selected complete document bytes exceed128MiB.");
for(const r of d.requirements){need(STATUS.includes(r.status),"Choose an explicit requirement state.");str(r.note,12000);str(r.reviewer,1000);str(r.decisionDate,40);need(!r.decisionDate||/^\d{4}-\d{2}-\d{2}$/.test(r.decisionDate),"Use an explicit ISO decision date.");need(Array.isArray(r.evidence)&&r.evidence.length<=100,"Keep a complete bounded evidence selection.");for(const e of r.evidence){need(object(e)&&docs.has(e.documentId),"Requirement evidence must retain its complete source document.");str(e.pages,500);str(e.locator,3000);}}
need(Array.isArray(d.slides)&&d.slides.length===o.script.slides.length,"Retain all12 authored slide positions.");let elapsed=0;for(let i=0;i<d.slides.length;i++){const s=d.slides[i],base=o.script.slides[i];need(s.id===base.id,"Keep original slide IDs/order.");for(const k of ["section","title","body","notes"])str(s[k],k==="notes"?12000:6000);need(Number.isFinite(s.seconds)&&s.seconds>0&&s.seconds<=240,"Use positive finite slide durations.");need(typeof s.isSectionSummary==="boolean","Keep an explicit summary flag.");elapsed+=s.seconds;}need(elapsed<=240,"Complete playback must fit240seconds.");need(d.slides.filter(s=>s.isSectionSummary).length===4,"Keep all four explicit section summaries.");
need(Array.isArray(d.assembly)&&d.assembly.length<=300,"Keep a bounded complete PDF assembly order.");for(const row of d.assembly){need(docs.has(row.documentId),"An assembly source is absent.");need(Array.isArray(row.pages)&&row.pages.length>0&&row.pages.length<=1000&&row.pages.every(x=>Number.isSafeInteger(x)&&x>0),"Select explicit one-based PDF pages.");str(row.note,3000);}for(const key of ["matrix","summaries"]){const v=d[key];need(object(v)&&typeof v.reviewed==="boolean","Keep original-source review choices.");str(v.documentId,200);str(v.reviewer,1000);str(v.note,12000);need(!v.documentId||docs.has(v.documentId),"The reviewed original source is absent.");if(v.reviewed)need(v.documentId&&v.reviewer.trim()&&v.note.trim(),"A source review requires original document, reviewer and full note.");}need(Number.isSafeInteger(d.matrix.page)&&d.matrix.page>0,"Select the actual matrix page.");return d;}
async function verifyDocuments(d,objects){for(const f of d.documents){const saved=objects[f.sha256];need(saved&&saved.bytes===f.bytes,"A complete original document is missing: "+f.name);}return d;}
async function validate(w,context){need(object(w)&&w.format===FORMAT,"Use a complete HCPS production workspace.");str(w.workspaceId,200);need(w.workspaceId,"Keep the original workspace identity.");str(w.title,1000);await validateSeed(w.seed);need(object(w.objects),"Keep all complete original document objects.");let totalObjects=0;for(const [key,value] of Object.entries(w.objects)){need(/^[a-f0-9]{64}$/.test(key)&&object(value),"An original object identity is invalid.");const raw=unb64(value.base64);need(raw.length===value.bytes&&await sha(raw)===key,"A retained original object differs.");totalObjects+=raw.length;}need(totalObjects<=512*1024*1024,"Retained original history exceeds512MiB.");validateDraft(w.draft,w.seed);await verifyDocuments(w.draft,w.objects);need(Array.isArray(w.editions)&&w.editions.length<=128,"Keep at most128 reviewed editions.");let parent="";const ids=new Set();for(let i=0;i<w.editions.length;i++){const e=w.editions[i];need(e.number===i+1&&!ids.has(e.id)&&e.parentSha256===parent,"The immutable edition chain differs.");ids.add(e.id);str(e.id,200);str(e.actor,1000);str(e.note,12000);str(e.createdAt,100);need(e.actor.trim()&&e.note.trim(),"Reviewed editions require attribution and purpose.");validateDraft(e.draft,w.seed);await verifyDocuments(e.draft,w.objects);need(e.draftSha256===await sha(canonical(e.draft)),"A reviewed complete edition differs.");const material={id:e.id,number:e.number,parentSha256:e.parentSha256,createdAt:e.createdAt,actor:e.actor,note:e.note,draftSha256:e.draftSha256};need(e.sha256===await sha(canonical(material)),"A reviewed edition identity differs.");parent=e.sha256;}need(Array.isArray(w.receiving)&&w.receiving.length<=1000,"Keep complete bounded incoming custody.");for(const r of w.receiving){need(object(r)&&/^[a-f0-9]{64}$/.test(r.packageSha256),"Keep incoming complete package identity.");str(r.sourceWorkspaceId,200);str(r.receivedAt,100);}if(w.returnReview){const R=global.HCPSReturns||(typeof require==="function"?require("./hcps-return.cjs"):null);need(R,"Open the complete response application with its whole return-review module.");await R.validateHistory(w,context);}return w;}
async function addDocument(w,{name,mediaType,raw,role="evidence",sourceUrl="",note=""}){need(raw instanceof Uint8Array,"Use complete original file bytes.");need(raw.length<=MAX_FILE,"An original file exceeds32MiB.");const d={id:id(),name,mediaType,bytes:raw.length,sha256:await sha(raw),role,sourceUrl,note};const retained=Object.values(w.objects).reduce((n,item)=>n+item.bytes,0)+(w.objects[d.sha256]?0:raw.length);need(retained<=512*1024*1024,"Retained original history would exceed512MiB; the prior complete working copy is unchanged.");const next=clone(w);next.objects[d.sha256]={bytes:raw.length,base64:b64(raw)};next.draft.documents.push(d);validateDraft(next.draft,next.seed);if(next.returnReview){const R=global.HCPSReturns||(typeof require==="function"?require("./hcps-return.cjs"):null);need(R,"Retain the complete return-review module.");R.sourceBudget(next);}return next;}
async function saveEdition(w,{actor,note,at=new Date().toISOString(),editionId=id()}){await validate(w);need(actor.trim()&&note.trim(),"Name the reviewer and describe the whole saved edition.");need(w.editions.length<128,"Export the whole history before starting another production workspace.");str(editionId,200);need(editionId&&!w.editions.some(e=>e.id===editionId),"Use a unique retained edition request identity.");const next=clone(w),draft=clone(w.draft);const item={id:editionId,number:next.editions.length+1,parentSha256:next.editions.at(-1)?.sha256||"",createdAt:at,actor,note,draftSha256:await sha(canonical(draft))};item.sha256=await sha(canonical(item));item.draft=draft;next.editions.push(item);return next;}
function compare(a,b){const changes=[];function walk(x,y,p){if(equal(x,y))return;if(object(x)&&object(y)){for(const k of new Set([...Object.keys(x),...Object.keys(y)])){const xp=Object.hasOwn(x,k),yp=Object.hasOwn(y,k);if(xp&&yp)walk(x[k],y[k],p+"/"+k.replace(/~/g,"~0").replace(/\//g,"~1"));else changes.push({path:p+"/"+k,before:{present:xp,...(xp?{value:clone(x[k])}:{})},after:{present:yp,...(yp?{value:clone(y[k])}:{})}});}return;}changes.push({path:p,before:{present:true,value:clone(x)},after:{present:true,value:clone(y)}});}walk(a,b,"");return changes;}
async function pack(w){await validate(w);const content=canonical(w);return canonical({format:"commons.hcps.response-package.v1",bytes:bytes(content).length,sha256:await sha(content),workspace:w});}
async function receive(raw){str(raw,800*1024*1024);const p=JSON.parse(raw);need(object(p)&&p.format==="commons.hcps.response-package.v1","Receive the complete original workspace package.");const content=canonical(p.workspace);need(p.bytes===bytes(content).length&&p.sha256===await sha(content),"The complete incoming package identity differs.");await validate(p.workspace);const next=clone(p.workspace);next.receiving.push({sourceWorkspaceId:next.workspaceId,packageSha256:await sha(raw),receivedAt:new Date().toISOString()});return next;}
async function manifest(w){validateDraft(w.draft,w.seed);const draftSha256=await sha(canonical(w.draft)),matching=w.editions.findLast(e=>e.draftSha256===draftSha256);const docs=new Map(w.draft.documents.map(d=>[d.id,d]));return{format:"commons.hcps.response-assembly.v1",workspaceId:w.workspaceId,sourceSolicitation:"0562FAC-RFQ-2027",draftSha256,selectedEdition:matching?.sha256||null,rows:w.draft.assembly.map((r,i)=>({position:i+1,...clone(r),document:((d)=>({id:d.id,name:d.name,bytes:d.bytes,sha256:d.sha256,mediaType:d.mediaType}))(docs.get(r.documentId))})),instruction:"Assemble the actual signed cover first and actual signed checklist second, then approved complete forms in original checklist order. This manifest preserves exact original page selections; it does not sign or attest any form."};}
const api={FORMAT,MAX_FILE,MAX_TOTAL,STATUS,ROLE,clone,need,equal,canonical,bytes,sha,b64,unb64,id,original,newWorkspace,validateSeed,validateDraft,verifyDocuments,validate,ready,addDocument,saveEdition,compare,pack,receive,manifest};
global.HCPSCore=api;if(typeof module!=="undefined")module.exports=api;
})(typeof globalThis!=="undefined"?globalThis:window);

(function(){
"use strict";
const C=HCPSCore,seed=JSON.parse(document.getElementById("seed").textContent);
const $=id=>document.getElementById(id),text=(id,v)=>$(id).textContent=v;
let db,record,diskVersion=0,busy=false,blocked=false,pendingWrites=0,writes=Promise.resolve();
const message=(v,error=false)=>{text("message",v);$("message").className=error?"message error":"message";};
function request(req){return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function transaction(tx){return new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error("Original storage operation aborted."));});}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open("hcps-response-production-v1",1);req.onupgradeneeded=()=>{for(const n of ["copies","objects","sources"])req.result.createObjectStore(n,{keyPath:"id"});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function snapshot(r){const w=C.clone({...r.workspace,objects:{},seed:null});delete w.objects;delete w.seed;return{id:r.id,name:r.name,workspace:w,seedSha256:r.seedSha256,objectKeys:Object.keys(r.workspace.objects),raw:C.clone(r.raw),ui:C.clone(r.ui),incomingPackageSha:r.incomingPackageSha||null,version:0,updatedAt:new Date().toISOString()};}
async function persistSnapshot(s,original){const tx=db.transaction(["copies","objects","sources"],"readwrite"),done=transaction(tx),copies=tx.objectStore("copies");let failure=null,nextVersion;
const held=copies.get(s.id);held.onsuccess=()=>{const current=held.result;if((current?.version||0)!==diskVersion){failure=Error("This working copy changed in another window. Download your whole current work or save it as an independent copy before reopening the newer saved copy.");tx.abort();return;}nextVersion=diskVersion+1;s.version=nextVersion;copies.put(s);tx.objectStore("sources").put({id:original.seedSha256,seed:original.workspace.seed});for(const key of s.objectKeys){const source=original.workspace.objects[key],get=tx.objectStore("objects").get(key);get.onsuccess=()=>{if(get.result){if(get.result.bytes!==source.bytes||get.result.base64!==source.base64){failure=Error("An original document object differs.");tx.abort();}}else tx.objectStore("objects").put({id:key,...source});};}};
try{await done;}catch(e){throw failure||e;}diskVersion=nextVersion;return nextVersion;}
function retain(){if(!record)return Promise.resolve();pendingWrites++;const selected=record,s=snapshot(selected),original={seedSha256:selected.seedSha256,workspace:{seed:selected.workspace.seed,objects:{...selected.workspace.objects}}};writes=writes.catch(()=>{}).then(async()=>{if(blocked)throw Error("Resolve the saved working-copy conflict before replacing that copy.");await persistSnapshot(s,original);if(record===selected)text("persistence","Complete working copy retained locally at revision "+diskVersion+".");});writes.catch(e=>{blocked=true;text("persistence","The current work remains in this page. Download it or save an independent copy.");message(e.message,true);});const current=writes;current.finally(()=>{pendingWrites--;}).catch(()=>{});return current;}
async function flush(){await writes;if(blocked)throw Error("Download or save an independent working copy before continuing.");}
function setBusy(value){busy=value;document.body.setAttribute("aria-busy",String(value));document.querySelectorAll("button,input,select,textarea").forEach(e=>e.disabled=value);$("download-emergency").disabled=!record;if(!value)window.HCPSReturnUI?.controls();}
async function run(fn){if(busy)return;setBusy(true);try{await fn();}catch(e){message(e.message,true);}finally{setBusy(false);}}
async function allCopies(){const tx=db.transaction("copies","readonly");return await request(tx.objectStore("copies").getAll());}
async function copies(){const rows=(await allCopies()).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));const select=$("copies");select.replaceChildren();for(const row of rows){const o=document.createElement("option");o.value=row.id;o.textContent=row.name+" — "+row.updatedAt.replace("T"," ").slice(0,16);select.append(o);}if(record)select.value=record.id;}
async function load(id){const tx=db.transaction(["copies","sources","objects"],"readonly"),stored=await request(tx.objectStore("copies").get(id));C.need(stored,"The selected working copy is absent.");const source=await request(db.transaction("sources","readonly").objectStore("sources").get(stored.seedSha256));C.need(source,"Restore the complete original issuer source.");const objects={};for(const key of stored.objectKeys){const o=await request(db.transaction("objects","readonly").objectStore("objects").get(key));C.need(o,"An original retained document is absent.");objects[key]={bytes:o.bytes,base64:o.base64};}const w={...stored.workspace,seed:source.seed,objects};await C.validate(w);record={...stored,workspace:w};diskVersion=stored.version;blocked=false;render();await copies();message("Opened the complete retained working copy.");}
async function create(w=null,raw={},name="HCPS response working copy",incomingPackageSha=null,incomingUI=null){const workspace=w||C.newWorkspace(seed);await C.validate(workspace);record={id:C.id(),name,incomingPackageSha,workspace,seedSha256:await C.sha(C.canonical(workspace.seed)),raw:C.clone(raw),ui:{tab:"requirements",requirementId:"R01",slideId:"P01",sourcePath:seed.files[0].path,selectedEdition:"",...(incomingUI&&typeof incomingUI==="object"&&!Array.isArray(incomingUI)?C.clone(incomingUI):{})}};diskVersion=0;blocked=false;await retain();render();await copies();}
function options(el,rows,value){el.replaceChildren();for(const [id,label] of rows){const o=document.createElement("option");o.value=id;o.textContent=label;el.append(o);}el.value=value??"";}
function download(name,raw,type="application/json"){const url=URL.createObjectURL(new Blob([raw],{type})),a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function saveRaw(key,fields){record.raw[key]=fields;retain();}
function draft(){return record.workspace.draft;}
function input(id,value){$(id).value=value??"";}
function rawReq(){const r=draft().requirements.find(x=>x.id===record.ui.requirementId);return record.raw["requirement:"+r.id]||{status:r.status,note:r.note,reviewer:r.reviewer,decisionDate:r.decisionDate,evidence:JSON.stringify(r.evidence,null,2)};}
function rawSlide(){const s=draft().slides.find(x=>x.id===record.ui.slideId);return record.raw["slide:"+s.id]||{title:s.title,section:s.section,body:s.body,notes:s.notes,seconds:String(s.seconds),summary:s.isSectionSummary};}
function requirementFields(){return{status:$("requirement-status").value,note:$("requirement-note").value,reviewer:$("requirement-reviewer").value,decisionDate:$("requirement-date").value,evidence:$("requirement-evidence").value};}
function slideFields(){return{title:$("slide-title").value,section:$("slide-section").value,body:$("slide-body").value,notes:$("slide-notes").value,seconds:$("slide-seconds").value,summary:$("slide-summary").checked};}
function tableRow(cells){const tr=document.createElement("tr");for(const value of cells){const td=document.createElement("td");if(value instanceof Node)td.append(value);else td.textContent=String(value??"");tr.append(td);}return tr;}
function button(label,fn){const b=document.createElement("button");b.type="button";b.textContent=label;b.addEventListener("click",()=>run(fn));return b;}
function renderRequirement(){const base=C.original(record.workspace.seed).requirements.requirements.find(x=>x.id===record.ui.requirementId),r=rawReq();text("requirement-original",base.requirement);text("requirement-location","Issued page "+base.page+" · "+base.clause+" · "+base.owner);text("requirement-completion",base.completion);text("requirement-applicability",base.applicability+" · "+base.lifecycle);input("requirement-status",r.status);input("requirement-note",r.note);input("requirement-reviewer",r.reviewer);input("requirement-date",r.decisionDate);input("requirement-evidence",r.evidence);}
function renderRequirements(){const q=$("requirement-search").value.toLowerCase(),filter=$("requirement-filter").value,orig=C.original(record.workspace.seed).requirements.requirements,tbody=$("requirement-rows");tbody.replaceChildren();let shown=0;for(const r of draft().requirements){const base=orig.find(x=>x.id===r.id);if(filter&&r.status!==filter)continue;if(q&&!([r.id,base.requirement,base.category,r.note].join(" ").toLowerCase().includes(q)))continue;const open=button(r.id,async()=>{record.ui.requirementId=r.id;await retain();renderRequirement();});tbody.append(tableRow([open,base.requirement,r.status,base.page,r.evidence.length]));shown++;}text("requirement-count",shown+" of "+orig.length+" original requirements");renderRequirement();}
function renderSlide(){const s=rawSlide();for(const k of ["title","section","body","notes","seconds"])input("slide-"+k,s[k]);$("slide-summary").checked=s.summary;const b=draft().slides.find(x=>x.id===record.ui.slideId);text("slide-source-note",C.original(record.workspace.seed).script.slides.find(x=>x.id===b.id).notes);previewSlide({title:s.title,body:s.body,section:s.section,isSectionSummary:s.summary});}
function previewSlide(s){text("slide-preview-title",s.title);text("slide-preview-section",s.section);text("slide-preview-body",s.body);$("slide-preview").classList.toggle("summary",s.isSectionSummary);}
